 else{$uid=$user_id;$q=$conn->prepare("INSERT INTO `$tbl`(user_id,name,email,number,message) VALUES(?,?,?,?,?)");$q->bind_param('issss',$uid,$name,$email,$phone,$body);$q->execute();flash('success','Дякуємо! Ваше повідомлення збережено.');}
 redirect_to('contact.php');
